"""Deterministic, original CC0 social cues; append metadata without changing existing audio."""
from pathlib import Path
import json,math,wave,struct,random
root=Path(__file__).resolve().parents[1];folder=root/'assets/audio/sfx/social';folder.mkdir(parents=True,exist_ok=True)
rate=22050;rng=random.Random(5181);entries=[]
for id,duration in [('social-text',.38),('social-ring',2.5),('social-knock',.65),('social-milestone',.8)]:
 values=[]
 for i in range(round(duration*rate)):
  t=i/rate;fade=min(1,t/.008,(duration-t)/.025)
  if id=='social-text':v=sum(.18*math.exp(-max(0,t-start)*18)*math.sin(2*math.pi*f*(t-start)) for start,f in [(0,660),(.13,880)] if t>=start)
  elif id=='social-ring':v=.11*(math.sin(2*math.pi*523*t)+.65*math.sin(2*math.pi*659*t))*max(0,1-(t%.8)/.32) if t%.8<.32 else 0
  elif id=='social-knock':v=sum(.24*math.exp(-(t-start)*45)*(math.sin(2*math.pi*160*(t-start))+.25*rng.uniform(-1,1)) for start in [0,.22,.44] if 0<=t-start<.16)
  else:v=sum(.08*math.exp(-max(0,t-start)*5)*math.sin(2*math.pi*f*(t-start)) for start,f in [(0,440),(.12,554.37),(.24,659.25)] if t>=start)
  values.append(round(max(-.9,min(.9,v*fade))*32767))
 path=folder/(id+'.wav')
 with wave.open(str(path),'wb') as out:out.setnchannels(1);out.setsampwidth(2);out.setframerate(rate);out.writeframes(b''.join(struct.pack('<h',n) for n in values))
 entries.append(dict(id=id,src=str(path.relative_to(root)),title=id.replace('-',' ').title(),author='Notsims project',source='scripts/generate-social-audio.py',license='CC0-1.0',date='2026-10-16',originalFilename=path.name,modifications='Original deterministic synthesis; mono PCM16 22050 Hz',duration=duration,bytes=path.stat().st_size,kind='sfx'))
p=root/'assets/audio/library.json';library=json.loads(p.read_text());ids={a['id'] for a in entries};library['assets']=[a for a in library['assets'] if a['id'] not in ids]+entries;p.write_text(json.dumps(library,indent=2)+'\n')
(root/'src/audio/audio-library.js').write_text('// Generated by scripts/generate-audio.py and scripts/generate-social-audio.py.\nexport const AUDIO_ASSETS='+json.dumps({a['id']:a for a in library['assets']},indent=2)+';\n')
print('Generated four original CC0 social cues.')
